'use strict';
/* brand.js is generated by the dashboard Settings and committed into the
   fork; its keys override config.js one by one, so config.js only has to
   carry the Supabase keys (a full legacy config keeps working as fallback). */
const CFG = (window.OPERATOR_CONFIG || window.OPERATOR_BRAND) ? Object.assign({}, window.OPERATOR_CONFIG || {}, window.OPERATOR_BRAND || {}) : null;
if(!CFG || !CFG.supabaseUrl || !CFG.supabaseKey){
  document.body.innerHTML = '<div style="max-width:540px;margin:80px auto;font-family:system-ui,sans-serif;line-height:1.5;padding:0 20px"><h2>Almost there</h2><p>This page needs its operator config. In your fork, copy <code>public/config.example.js</code> to <code>public/config.js</code> and fill in your values. SETUP.md walks through it.</p></div>';
  throw new Error('missing config.js');
}
const SUPABASE_URL = CFG.supabaseUrl;
const SUPABASE_KEY = CFG.supabaseKey;
const GNAME = Object.assign({ who_knows_who: 'Who Knows Who', guess_the_split: 'Guess the Split', quick_pour: 'Quick Pour' }, CFG.gameNames || {});
const db = supabase.createClient(SUPABASE_URL, SUPABASE_KEY);

const params = new URLSearchParams(location.search);
const V = params.get('v'), K = params.get('k');
let P = null;
const PASS_K = 'st_opass_' + V;   // shared with owner.html: session first, then a remembered device
try {
  P = sessionStorage.getItem(PASS_K) || null;
  if(!P){
    const raw = localStorage.getItem(PASS_K);
    if(raw){ let d = null; try { d = JSON.parse(raw); } catch(e){} if(d && d.p && d.exp > Date.now()) P = d.p; }
  }
} catch(e){}

const ACC = /^#[0-9a-f]{6}$/i.test(CFG.accent || '') ? CFG.accent : '#3a6ea5';
const HOST = location.host;
const REGION = CFG.regionShort || 'the county';
const LOGOSVG = (typeof CFG.logoSvg === 'string' && CFG.logoSvg.trim().startsWith('<svg')) ? CFG.logoSvg : '';
const ICONURL = (typeof CFG.iconUrl === 'string' && CFG.iconUrl) ? CFG.iconUrl : '';
const ST_SVG = '<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg"><rect x="10" y="10" width="44" height="44" rx="11" fill="' + ACC + '"/><text x="32" y="43" font-family="sans-serif" font-size="26" font-weight="800" fill="#fff" text-anchor="middle">' + esc((CFG.brandName || '?').trim().charAt(0).toUpperCase()) + '</text></svg>';
const ST_MARK = LOGOSVG || (ICONURL ? '<img src="' + esc(ICONURL) + '" alt="" style="width:18px;height:18px;display:block;object-fit:contain">' : ST_SVG);
document.title = 'Guest Report · ' + CFG.brandName;
(function(){ const fav = document.querySelector('link[rel="icon"]');
  if(fav) fav.href = ICONURL || 'data:image/svg+xml,' + encodeURIComponent(LOGOSVG || ST_SVG); })();

/* ---- period picker: last completed month by default, 18 months back, all time ---- */
const MONTHS = [];
(function(){
  const now = new Date();
  for(let i = 1; i <= 18; i++){
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    MONTHS.push({ y: d.getFullYear(), m: d.getMonth() });
  }
  MONTHS.unshift({ y: now.getFullYear(), m: now.getMonth(), partial: true });
})();
const mLabel = p => new Date(p.y, p.m, 1).toLocaleDateString([], { month:'long', year:'numeric' });
const iso = (y, m) => `${y}-${String(m+1).padStart(2,'0')}-01`;
function ranges(sel){
  if(sel === 'all') return { from:null, to:null, pf:null, pt:null, label:'All time' };
  const p = MONTHS[+sel];
  const from = iso(p.y, p.m), to = iso(p.m === 11 ? p.y+1 : p.y, (p.m+1) % 12);
  const prev = new Date(p.y, p.m - 1, 1);
  return { from, to, pf: iso(prev.getFullYear(), prev.getMonth()), pt: from,
           label: mLabel(p) + (p.partial ? ' (so far)' : '') };
}

function paintPicker(){
  $('period').innerHTML = MONTHS.map((p,i)=>`<option value="${i}">${mLabel(p)}${p.partial?' (so far)':''}</option>`).join('')
    + '<option value="all">All time</option>';
  $('period').value = '1';   // last completed month
}

/* ---- data ---- */
let FORM = null;
async function loadForm(fc){
  try {
    const { data } = await db.from('feedback_forms').select('*').in('id', fc ? ['global', V] : ['global']);
    const rows = {}; (data||[]).forEach(r=>{ rows[r.id]=r; });
    FORM = (fc && rows[V]) ? rows[V] : (rows.global || null);
  } catch(e){ FORM = null; }
}
async function fetchReport(sel){
  const r = ranges(sel);
  const { data, error } = await db.rpc('get_report', {
    p_venue_id: V, p_key: K, p_pass: P,
    p_from: r.from, p_to: r.to, p_pf: r.pf, p_pt: r.pt });
  if(error) throw error;
  return { data, r };
}

/* ---- rendering helpers ---- */
// County comparison toggle (41_report_county_venue.sql): the venue's
// public_venues row (already fetched for header branding) carries
// report_county; false hides the whole "vs county" page. A missing column
// (pre-41) or missing row = shown, the original behavior.
let RC = true;
const showCounty = () => RC;
const fmt = x => (x === null || x === undefined) ? '–' : (+x).toFixed(2).replace(/\.00$/,'').replace(/(\.\d)0$/,'$1');
function chip(cur, prev, unit){
  if(prev === null || prev === undefined || cur === null || cur === undefined) return '';
  const d = +(cur - prev).toFixed(2);
  if(!d) return `<span class="chip flat">even <span class="vs">vs prior</span></span>`;
  return `<span class="chip ${d > 0 ? 'up' : 'down'}">${d > 0 ? '▲ +' : '▼ '}${fmt(Math.abs(d)*(d>0?1:-1)).replace('-','')}${unit||''} <span class="vs">vs prior</span></span>`;
}
function bars(rows, total){
  if(!rows || !rows.length) return '<div class="empty">No answers in this period.</div>';
  const max = Math.max(...rows.map(r=>r.n), 1);
  return '<div class="rowbar">' + rows.map(r=>{
    const pct = total ? Math.round(100*r.n/total) : 0;
    return `<div class="r"><span class="lbl">${esc(r.k)}</span><span class="track"><span class="fill" style="width:${Math.round(100*r.n/max)}%"></span></span><span class="n"><b>${pct}%</b> · ${r.n}</span></div>`;
  }).join('') + '</div>';
}
function vsCountyBars(mine, county, totalMine){
  if(!mine || !mine.length) return '<div class="empty">No answers in this period.</div>';
  const cmap = {}; (county||[]).forEach(c=>{ cmap[c.k] = +c.pct; });
  return '<div class="rowbar">' + mine.map(r=>{
    const myPct = totalMine ? Math.round(100*r.n/totalMine) : 0;
    const cp = cmap[r.k];
    return `<div class="r"><span class="lbl">${esc(r.k)}</span><span class="track"><span class="fill" style="width:${myPct}%"></span>${cp !== undefined ? `<span class="mark" style="left:${Math.min(cp,100)}%"></span>` : ''}</span><span class="n"><b>${myPct}%</b>${cp !== undefined ? ` <span style="color:var(--ink-faint)">/ ${cp}%</span>` : ''}</span></div>`;
  }).join('') + '</div>';
}

function render(d, r){
  const cur = d.cur || {}, prev = d.prev, county = d.county || {};
  const ev = d.events || {}, evp = d.events_prev;
  const extras = (FORM && Array.isArray(FORM.extras)) ? FORM.extras : [];
  const exVals = qid => (d.extras || []).map(e => e && e[qid]).filter(x => x !== undefined && x !== null);
  const totalDisc = (d.discovery||[]).reduce((a,b)=>a+b.n,0);
  const totalPlate = (d.plate||[]).reduce((a,b)=>a+b.n,0);
  const totalVisit = (d.visit||[]).reduce((a,b)=>a+b.n,0);

  // custom aggregates (ratings + choices) for the main pages
  const customAgg = extras.filter(q=>q.type!=='text').map(q=>{
    const vals = exVals(q.id);
    if(q.type === 'rating'){
      const nums = vals.filter(x=>typeof x==='number');
      const avg = nums.length ? (nums.reduce((a,b)=>a+b,0)/nums.length) : null;
      return `<div class="card"><div class="k">${esc(q.label)}</div><div class="n">${avg===null?'–':fmt(avg)}<small> / 5</small></div><div class="note">${nums.length} answer${nums.length===1?'':'s'}</div></div>`;
    }
    const counts = {};
    vals.forEach(x=>{ (Array.isArray(x)?x:[x]).forEach(o=>{ counts[o]=(counts[o]||0)+1; }); });
    const rows = Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,n])=>({k,n}));
    const tot = rows.reduce((a,b)=>a+b.n,0);
    return `<div class="card" style="grid-column:1/-1"><div class="k">${esc(q.label)}</div>${bars(rows, tot)}</div>`;
  }).join('');

  // appendix: comments + text extras
  const textQs = extras.filter(q=>q.type==='text');
  const appendix =
    ((d.comments||[]).length ? `
      <div class="sec pagebreak">
        <h2>Guest comments · ${esc(r.label)}</h2>
        ${d.comments.map(c=>`<div class="comment"><div>${esc(c.t)}</div><div class="at">${new Date(c.at).toLocaleDateString([], {month:'short', day:'numeric', year:'numeric'})}</div></div>`).join('')}
      </div>` : '') +
    textQs.map(q=>{
      const texts = exVals(q.id).filter(x=>typeof x==='string');
      if(!texts.length) return '';
      return `<div class="sec pagebreak"><h2>${esc(q.label)} · ${esc(r.label)}</h2>${texts.map(t=>`<div class="comment"><div>${esc(t)}</div></div>`).join('')}</div>`;
    }).join('');

  $('sheet').innerHTML = `
    <div class="rhead">
      <div class="vlogo">${/^(https?:|images\/)/i.test(d.logo||'') ? `<img src="${esc(d.logo)}" alt="${esc(d.name)}" />` : `<div class="vname">${esc(d.logo || d.name)}</div>`}</div>
      <div class="rmeta"><div class="k">Guest report</div><div class="d">${esc(r.label)} · ${cur.count||0} guest${cur.count===1?'':'s'} responded</div></div>
    </div>

    <div class="sec">
      <h2>Your scores · private to you</h2>
      <div class="cards">
        <div class="card"><div class="k">Food</div><div class="n">${fmt(cur.food)}<small> / 5</small></div>${prev ? chip(cur.food, prev.food) : ''}</div>
        <div class="card"><div class="k">Service</div><div class="n">${fmt(cur.service)}<small> / 5</small></div>${prev ? chip(cur.service, prev.service) : ''}</div>
      </div>
    </div>

    <div class="sec">
      <h2>How they found you</h2>
      ${bars(d.discovery, totalDisc)}
    </div>

    <div class="sec">
      <h2>Activity</h2>
      <div class="grid3">
        <div class="card"><div class="k">App opens</div><div class="n">${ev.opens||0}</div>${evp ? chip(ev.opens||0, evp.opens||0) : ''}</div>
        <div class="card"><div class="k">Sent to Google</div><div class="n">${ev.review_clicks||0}</div>${evp ? chip(ev.review_clicks||0, evp.review_clicks||0) : ''}</div>
        <div class="card"><div class="k">Card taps</div><div class="n">${(ev.card_opens||0)+(ev.promo_clicks||0)}</div>${evp ? chip((ev.card_opens||0)+(ev.promo_clicks||0), (evp.card_opens||0)+(evp.promo_clicks||0)) : ''}</div>
      </div>
    </div>

    ${(d.games||[]).length ? `
    <div class="sec">
      <h2>Game starts · all time</h2>
      ${bars(d.games.map(g=>({k:({guess_the_split:'Guess the Split',who_knows_who:'Who Knows Who',wordy:'Wordy',trivia:'Trivia',who_invited_you:'Who Invited You?',fortune_teller:'Fortune Teller',all_talk:'All Talk',cornhole:'Cornhole',quick_pour:GNAME.quick_pour})[g.game]||g.game, n:g.plays})), d.games.reduce((a,b)=>a+b.plays,0))}
    </div>` : ''}

    ${customAgg ? `
    <div class="sec">
      <h2>Your custom questions · ${esc(r.label)}</h2>
      <div class="cards">${customAgg}</div>
    </div>` : ''}

    ${showCounty() ? `
    <div class="sec pagebreak">
      <h2>Your guests vs ${esc(REGION)}</h2>
      <div class="note" style="margin-top:8px">The ${esc(REGION)} numbers are the anonymous average across the ${esc(CFG.brandName)} network. Your venue's answers are the bars; the dark mark is ${esc(REGION)}.</div>
      <div class="cards" style="margin-top:12px">
        <div class="card"><div class="k">Food · you vs ${esc(REGION)}</div><div class="n">${fmt(cur.food)} <small>/ ${fmt(county.food)}</small></div></div>
        <div class="card"><div class="k">Service · you vs ${esc(REGION)}</div><div class="n">${fmt(cur.service)} <small>/ ${fmt(county.service)}</small></div></div>
      </div>
      <div class="sec"><h2>How they found you · vs ${esc(REGION)}</h2>${vsCountyBars(d.discovery, county.discovery, totalDisc)}</div>
      <div class="sec"><h2>In the food, what matters most · vs ${esc(REGION)}</h2>${vsCountyBars(d.plate, county.plate, totalPlate)}</div>
      <div class="sec"><h2>About the visit, what matters most · vs ${esc(REGION)}</h2>${vsCountyBars(d.visit, county.visit, totalVisit)}</div>
      <div class="legend"><span><span class="sw"></span>Your venue</span><span><span class="mk"></span>${esc(REGION)} average</span></div>
    </div>` : ''}

    ${appendix}

    <div class="stfoot">${ST_MARK} ${esc(CFG.brandName)} · ${esc(HOST)}</div>`;
}

/* ---- venue branding: same anon view the diner app reads. The header band
   takes the venue's app header color (header_bg, or the dark nav when the
   venue runs dark mode) and the page accent becomes the venue accent. ---- */
async function applyBrand(){
  try {
    const { data: b } = await db.from('public_venues').select('*').eq('id', V).maybeSingle();
    if(!b) return;
    RC = b.report_county !== false;
    const r = document.documentElement.style;
    if(/^#[0-9a-f]{6}$/i.test(b.accent || '')) r.setProperty('--accent', b.accent);
    const head = b.header_bg || (b.dark_mode ? '#0b0a09' : null);
    if(head){
      r.setProperty('--vhead', head);
      if(readableOn(head) === '#ffffff'){
        r.setProperty('--vhead-ink', '#f2efe9');
        r.setProperty('--vhead-dim', 'rgba(255,255,255,.66)');
      }
    }
  } catch(e){}
}

/* ---- boot ---- */
async function boot(){
  if(!V || !K){ document.body.innerHTML = '<div id="gate" style="display:block"><h1>Guest report</h1><p>This link is missing its key. Use the link from your dashboard email.</p></div>'; return; }
  paintPicker();
  // awaited: the county flag must be known before the first render (the
  // band colors ride along; it is one indexed select, cheap)
  await applyBrand();
  await run();
}
async function run(){
  const sel = $('period').value || '1';
  let res;
  try { res = await fetchReport(sel); }
  catch(e){ $('gate').style.display='block'; $('gate').querySelector('p').textContent='Could not load the report. Check the link, or try again.'; $('gatePass').style.display='none'; $('gateGo').style.display='none'; return; }
  const d = res.data;
  if(d === null){ $('gate').style.display='block'; $('gate').querySelector('p').textContent='This link is not valid. Ask for a fresh one.'; $('gatePass').style.display='none'; $('gateGo').style.display='none'; return; }
  if(d && d.need_pass){
    $('toolbar').style.display='none'; $('sheet').style.display='none'; $('gate').style.display='block';
    if(d.locked){ $('gate').querySelector('p').textContent='Too many passphrase tries. Wait fifteen minutes, then open this link again.'; $('gatePass').style.display='none'; $('gateGo').style.display='none'; }
    return;
  }
  // the passphrase is kept for this tab only once the server has accepted it
  if(P){ try { sessionStorage.setItem(PASS_K, P); } catch(e){} }
  if(FORM === null) await loadForm(d.form_custom);
  $('gate').style.display='none';
  $('toolbar').style.display='flex';
  $('sheet').style.display='block';
  render(d, res.r);
}
$('gateGo').onclick = async ()=>{
  const p = $('gatePass').value;
  if(!p){ $('gateMsg').textContent = 'Enter the passphrase.'; return; }
  P = p;
  $('gateMsg').textContent = '';
  await run();
  if($('gate').style.display !== 'none') $('gateMsg').textContent = 'That passphrase did not work.';
};
$('gatePass').addEventListener('keydown', e=>{ if(e.key==='Enter') $('gateGo').click(); });
$('period').addEventListener('change', run);
$('printBtn').onclick = ()=> window.print();
boot();
